import{_ as a,c as o,o as s,ah as r,ao as n,ap as i}from"./chunks/framework.Dq2_gudl.js";const h=JSON.parse('{"title":"Permiso para llorar — Dios guarda tus lágrimas en un frasco","description":"Llorar por una mascota no es falta de fe. Los Salmos dicen que Dios recoge nuestras lágrimas en un frasco y las registra en Su libro.","frontmatter":{"title":"Permiso para llorar — Dios guarda tus lágrimas en un frasco","description":"Llorar por una mascota no es falta de fe. Los Salmos dicen que Dios recoge nuestras lágrimas en un frasco y las registra en Su libro."},"headers":[],"relativePath":"es/pets-in-heaven/permission-to-grieve.md","filePath":"es/pets-in-heaven/permission-to-grieve.md"}'),l={name:"es/pets-in-heaven/permission-to-grieve.md"};function t(p,e,u,c,d,m){return s(),o("div",null,[...e[0]||(e[0]=[r('<div class="pl-quote"><p>«Ya pasaron meses y sigo llorando. ¿No soy lo bastante fuerte? ¿Mi fe es muy pequeña?»</p><p class="pl-quote-soft">La Biblia nunca trata las lágrimas como prueba de fracaso. Todo lo contrario.</p></div><section class="pl-section"><h2>1. Dios guarda las lágrimas en un frasco</h2><blockquote><p><strong>Salmos 56:8</strong></p><p>&quot;Thou tellest my wanderings: put thou my tears into thy bottle: are they not in thy book?&quot;</p></blockquote><p>David escribió esto desde un sufrimiento profundo. Pide a Dios que guarde sus lágrimas en un frasco y las registre en un libro: en el mundo antiguo, un frasco de lágrimas era una colección preciosa, la prueba de que «esta persona lloró por esto».</p><p>Lo que significa: <strong>tus lágrimas no son algo que cae y desaparece.</strong> Ni una gota se pierde. Cada lágrima que derramaste por él es recogida. Es registrada.</p><p>Así que cuando pienses «¿estaré llorando demasiado?», recuerda: para Dios eso no es ruido. Es un registro.</p></section><section class="pl-section"><h2>2. Dios se acerca a los quebrantados — no los reprende</h2><blockquote><p><strong>Salmos 34:18</strong></p><p>&quot;The LORD is nigh unto them that are of a broken heart; and saveth such as be of a contrite spirit.&quot;</p></blockquote><blockquote><p><strong>Salmos 147:3</strong></p><p>&quot;He healeth the broken in heart, and bindeth up their wounds.&quot;</p></blockquote><p>Fíjate en los verbos: Él <em>se acerca</em>. Él <em>sana</em>. Él <em>venda</em>. Lo primero que Dios hace con quien sufre no es exigirle que se recomponga: es caminar hacia él.</p><p>Jesús también dijo una frase corta:</p><blockquote><p><strong>Mateo 5:4</strong></p><p>&quot;Blessed are they that mourn: for they shall be comforted.&quot;</p></blockquote><p>«Bienaventurados los que lloran.» A los que sufren no se les reprende: se les declara bienaventurados, porque el consuelo viene. No es «deberías animarte», sino «serás consolado».</p></section><section class="pl-section"><h2>3. El duelo no es lo contrario del amor: es el amor que continúa</h2><p>No lloramos por lo que nunca amamos. La razón de que duela tanto es que realmente hubo amor entre ustedes.</p><p>Dios nos hizo seres que lloran por las pérdidas. Jesús mismo lloró ante el sepulcro de Lázaro (Juan 11:35): sabiendo que en minutos lo resucitaría, igual lloró.</p><p>Así que no le debes disculpas a nadie por tus lágrimas. No te falta fe. Simplemente estás herido en el amor.</p><p class="pl-quote-soft">Si quieres, puedes orar así:</p></section><div class="pl-quote"><p>«Señor, Tú sabes cuántas veces he llorado.<br>Gracias por no apurarme a estar bien, y por guardar cada lágrima en Tu frasco.<br>Acércate a mí, como te acercas a todo corazón quebrantado;<br>sáname, y por favor cuida al que extraño.<br>Hoy no quiero ser fuerte. Solo quiero que me abraces. Amén.»</p></div><section class="pl-section"><h2>Cuatro cosas que puedes hacer por ti ahora</h2><div class="pl-moment-grid"><div class="pl-moment"><span class="pl-moment-icon">🌊</span><h3>No decidas nada en el pico</h3><p>Las olas del duelo pasan. En el peor momento, basta con sobrevivir los próximos cinco minutos. No resuelvas nada más.</p></div><div class="pl-moment"><span class="pl-moment-icon">🍽️</span><h3>Cuida el cuerpo primero</h3><p>Bebe agua. Come algo. Duerme. El duelo desgasta el cuerpo, y un cuerpo con hambre hace doler más el corazón.</p></div><div class="pl-moment"><span class="pl-moment-icon">📝</span><h3>Escríbelo en un cuaderno</h3><p>No necesita ser bonito. Escribe un detalle: cómo te despertaba, su expresión favorita. Dale a la añoranza un lugar donde estar.</p></div><div class="pl-moment"><span class="pl-moment-icon">🤝</span><h3>Busca a alguien que de verdad entienda</h3><p>No todos entienden llorar por un animal, pero algunos sí. Si no lo encuentras, escríbelo: Dios puede leerlo.</p></div></div></section><section class="pl-section"><h2>Ese día llegará</h2><p>Apocalipsis promete que un día Dios mismo enjugará toda lágrima de nuestros ojos, y no habrá más muerte, ni tristeza, ni llanto, ni dolor (Apocalipsis 21:4). En ese día descubrirás que cada lágrima que derramaste por él fue recordada y respondida por un Dios bueno.</p><p>Mientras tanto, date permiso para llorar. Es una forma más de seguir amándolo.</p><p><a href="/es/pets-in-heaven/">← Volver a Pets in Heaven</a> ｜ Primera lectura: <a href="/es/pets-in-heaven/will-i-see-my-pet-again">¿Volveré a ver a mi mascota?</a></p></section><div class="pl-cta"><h2>Hoy, una frase es suficiente.</h2><p>PetLoss incluye un diario guiado y un compañero SOS que ofrece palabras de anclaje en los momentos más pesados. Sin cuenta, sin subidas, totalmente offline.</p><a class="pl-download" href="https://apps.apple.com/us/app/petloss-memorial-healing/id6757967412">Descargar en el App Store</a></div><div class="pl-bible"><h3>Deja que la Palabra te siga acompañando</h3><p>Todos los versículos de este artículo provienen de la Biblia. Con Rainbow Bible puedes leer las Escrituras en cualquier momento y poner un widget con el versículo del día: una pequeña luz en los días en que lo echas de menos.</p><div class="pl-bible-shots"><figure><img src="'+n+'" alt="Widget de Rainbow Bible mostrando 2 Timoteo 2:13" loading="lazy"><figcaption>Versículo del día en tu pantalla</figcaption></figure><figure><img src="'+i+'" alt="Rainbow Bible — tema Mascotas en el cielo mostrando Mateo 10:29-31" loading="lazy"><figcaption>Lee las Escrituras en Mascotas en el cielo</figcaption></figure></div><a class="pl-bible-download" href="https://apps.apple.com/app/id6756217525">Descargar Rainbow Bible en el App Store</a></div>',9)])])}const b=a(l,[["render",t]]);export{h as __pageData,b as default};
